package com.hrflow.platform.dashboard;
import com.hrflow.platform.common.ApiModels.Dashboard; import com.hrflow.platform.department.DepartmentRepository; import com.hrflow.platform.employee.EmployeeRepository; import com.hrflow.platform.leave.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class DashboardService {private final EmployeeRepository employees;private final DepartmentRepository departments;private final LeaveRequestRepository leaves;@Transactional(readOnly=true)public Dashboard summary(){Map<String,Long> byDepartment=new LinkedHashMap<>();employees.countGroupedByDepartment().forEach(x->byDepartment.put((String)x[0],(Long)x[1]));Map<String,Long> byStatus=new LinkedHashMap<>();for(LeaveStatus s:LeaveStatus.values())byStatus.put(s.name(),0L);leaves.countGroupedByStatus().forEach(x->byStatus.put(((LeaveStatus)x[0]).name(),(Long)x[1]));return new Dashboard(employees.count(),employees.countByActiveTrue(),departments.count(),leaves.countByStatus(LeaveStatus.PENDING),byDepartment,byStatus);}}
